var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

return {
  draw: function(ctx, W, H, t, dt) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    var cx = W / 2, cy = H / 2 + Math.min(W, H) * 0.15;
    var legLen = Math.min(W, H) * 0.28;
    var cycle = 240;
    var phase = t % cycle;
    var x, y;
    if (phase < cycle / 2) {
      var p = phase / (cycle / 2);
      x = cx;
      y = cy - p * legLen;
    } else {
      var p = (phase - cycle / 2) / (cycle / 2);
      x = cx + p * legLen;
      y = cy - legLen;
    }
    ctx.strokeStyle = '#9CA3AF';
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    if (phase < cycle / 2) {
      ctx.lineTo(x, y);
    } else {
      ctx.lineTo(cx, cy - legLen);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = '#E8593C';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(x, y);
    ctx.stroke();
    var angle = Math.atan2(y - cy, x - cx);
    ctx.fillStyle = '#E8593C';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 10 * Math.cos(angle - 0.4), y - 10 * Math.sin(angle - 0.4));
    ctx.lineTo(x - 10 * Math.cos(angle + 0.4), y - 10 * Math.sin(angle + 0.4));
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#059669';
    ctx.beginPath();
    ctx.arc(cx, cy, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#E8593C';
    ctx.beginPath();
    ctx.arc(x, y, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#374151';
    ctx.font = '12px sans-serif';
    ctx.fillText('grey dashed = distance traveled, orange arrow = displacement', 14, 20);
  }
};

var startX = null, startY = null, curX = null, curY = null, path = [];
return {
  init: function(api) {
    startX = api.width / 2;
    startY = api.height / 2;
    curX = startX;
    curY = startY;
    path = [{ x: startX, y: startY }];
  },
  onDragStart: function(x, y) {
    startX = x;
    startY = y;
    curX = x;
    curY = y;
    path = [{ x: x, y: y }];
  },
  onDrag: function(x, y) {
    curX = x;
    curY = y;
    path.push({ x: x, y: y });
  },
  draw: function(ctx, W, H) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    if (startX === null) return;
    ctx.strokeStyle = '#9CA3AF';
    ctx.setLineDash([4, 4]);
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(path[0].x, path[0].y);
    for (var i = 1; i < path.length; i++) ctx.lineTo(path[i].x, path[i].y);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = '#E8593C';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(curX, curY);
    ctx.stroke();
    var angle = Math.atan2(curY - startY, curX - startX);
    ctx.fillStyle = '#E8593C';
    ctx.beginPath();
    ctx.moveTo(curX, curY);
    ctx.lineTo(curX - 12 * Math.cos(angle - 0.4), curY - 12 * Math.sin(angle - 0.4));
    ctx.lineTo(curX - 12 * Math.cos(angle + 0.4), curY - 12 * Math.sin(angle + 0.4));
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#059669';
    ctx.beginPath();
    ctx.arc(startX, startY, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#E8593C';
    ctx.beginPath();
    ctx.arc(curX, curY, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#374151';
    ctx.font = '12px sans-serif';
    ctx.fillText('Drag the dot: grey = distance traveled, orange arrow = displacement', 10, 20);
  }
};
